gO8(){return"\u091f\u0940\u092e \u0938\u0926\u0938\u094d\u092f \u0938\u0902\u092a\u093e\u0926\u093f\u0924 \u0915\u0930\u0947\u0902"},
gOe(){return"\u092b\u093c\u094b\u0928 (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gOx(){return"\u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 \u092a\u093f\u0928 (4+ \u0905\u0902\u0915)"},
gOw(){return"\u0935\u0947 \u0938\u093e\u0907\u0928 \u0907\u0928 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0907\u0938\u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0917\u0947 \u2014 \u0907\u0938\u0915\u0947 \u092c\u093f\u0928\u093e \u0909\u0928\u094d\u0939\u0947\u0902 \u092c\u0928\u093e\u092f\u093e \u0928\u0939\u0940\u0902 \u091c\u093e \u0938\u0915\u0924\u093e\u0964"},
gOr(){return"\u092d\u0942\u092e\u093f\u0915\u093e"},
gOv(){return"\u092c\u093f\u0915\u094d\u0930\u0940 \u091f\u0940\u092e"},
gRL(){return"\u0916\u093e\u0924\u093e \u0932\u0947\u092c\u0932"},
